#!/usr/bin/env node
// Project-owned syntax gate (not generated by bench-quality-cli).
//
// `node --check` every JavaScript/ESM file this repository ships or executes,
// using the *running* node — so a syntax feature that only the minimum
// supported runtime lacks (24.15.0) surfaces in the compatibility CI job
// instead of on a consumer's machine.
import { execFileSync } from "node:child_process";
import { readdirSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SKIP_DIRS = new Set(["node_modules", ".git", ".husky", "coverage"]);
const ROOTS = ["bin", "src", "templates", "scripts", "tests"];

const files = [];
function walk(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (SKIP_DIRS.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full);
    else if (/\.m?js$/.test(entry.name)) files.push(full);
  }
}

for (const candidate of ROOTS) {
  const full = path.join(root, candidate);
  try {
    if (statSync(full).isDirectory()) walk(full);
  } catch {
    // Optional directory (for example templates before the first feature ships).
  }
}

const failures = [];
for (const file of files.sort()) {
  try {
    execFileSync(process.execPath, ["--check", file], { stdio: "pipe" });
  } catch (error) {
    failures.push({ file: path.relative(root, file), output: String(error.stderr ?? error.message) });
  }
}

for (const failure of failures) {
  console.error(`SYNTAX_ERROR: ${failure.file}`);
  console.error(failure.output.trimEnd());
}
if (failures.length > 0) {
  console.error(`\n${failures.length}/${files.length} file(s) failed node --check with ${process.version}.`);
  process.exit(1);
}
console.log(`Syntax check passed: ${files.length} file(s) parsed by ${process.version}.`);
